// 真实 Chrome + IndexedDB；临时用户目录，不访问已安装扩展或用户摘录。
import { spawn, execFileSync } from 'node:child_process';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve, join } from 'node:path';
import { createServer } from 'vite';

const baseline = process.argv.includes('--baseline');
const writes = process.argv.includes('--writes');
const searchProjection = process.argv.includes('--search-projection');
const search = process.argv.includes('--search') || searchProjection;
const highlightScheduling = process.argv.includes('--highlight-scheduling');
const textMapping = process.argv.includes('--text-mapping');
const highlights = process.argv.includes('--highlights') || highlightScheduling || textMapping;
const cache = process.argv.includes('--cache');
const index = process.argv.includes('--index');
const normalize = process.argv.includes('--normalize');
const urlRead = process.argv.includes('--url-read');
const pageCache = process.argv.includes('--page-cache');
const writeLayout = process.argv.includes('--write-layout');
const keyLayout = process.argv.includes('--key-layout');
const allocations = process.argv.includes('--allocations');
if (process.env.PROFILE && allocations) throw new Error('Run CPU profiling separately from allocation sampling');
if (allocations && !cache && !index && !normalize && !urlRead && !pageCache && !keyLayout && !highlights && (!search || searchProjection)) throw new Error('--allocations requires a cache, search or highlight benchmark');
if (urlRead && baseline) throw new Error('--url-read compares the current cache path and experimental strategies in one run');
if (searchProjection && baseline) throw new Error('--search-projection compares the current query path and experimental store in one run');
const baselineRef = baseline
  ? execFileSync('git', ['rev-parse', process.env.BASELINE_REF ?? 'HEAD'], { encoding: 'utf8' }).trim()
  : undefined;
const legacyUrlLookup = baseline && !writes && !search && !highlights && !cache && !index && !normalize && !/async getByUrl\(/.test(
  execFileSync('git', ['show', `${baselineRef}:src/background/storage/cache-manager.ts`], { encoding: 'utf8' })
);
const profile = await mkdtemp(join(tmpdir(), 'clipsey-perf-'));
const server = await createServer({
  configFile: false,
  logLevel: 'silent',
  resolve: { alias: { '@': resolve('src') } },
  server: { host: '127.0.0.1', port: 0 },
  plugins: [{
    name: 'performance-page',
    load(id) {
      if (!baseline) return;
      const path = id.split('?')[0];
      const databaseFiles = ['src/background/indexeddb.ts', 'src/background/indexeddb-query.ts', 'src/types/indexeddb.ts', 'src/background/storage/utils/clip-url-record.ts'];
      const cacheFiles = ['src/background/storage.ts', 'src/background/storage/cache-manager.ts', 'src/background/storage/clip-index.ts', 'src/background/storage/utils/clip-normalizer.ts'];
      const files = pageCache || writeLayout || keyLayout ? [...cacheFiles, ...databaseFiles] : writes
        ? ['src/background/storage.ts', 'src/background/storage/sync-manager.ts', 'src/background/storage/utils/clip-normalizer.ts', ...databaseFiles]
        : normalize ? ['src/background/storage/utils/clip-normalizer.ts']
        : index ? ['src/background/storage/clip-index.ts']
        : cache ? [...cacheFiles, ...databaseFiles]
        : search ? ['src/background/services/search-service.ts', ...databaseFiles]
        : highlights ? ['src/content/highlight/dom-utils.ts', 'src/content/highlight/metadata.ts', 'src/content/highlight/locators/offset-locator.ts', 'src/content/highlight/text-search.ts', 'src/content/highlight-engine.ts']
        : ['src/background/storage/cache-manager.ts', 'src/background/indexeddb-query.ts', 'src/background/storage/clip-index.ts', 'src/background/storage/utils/clip-normalizer.ts'];
      if (files.some(file => path === resolve(file))) {
        return execFileSync('git', ['show', `${baselineRef}:${path.slice(resolve('.').length + 1)}`], { encoding: 'utf8' });
      }
      if (legacyUrlLookup && path === resolve('tests/performance/browser.ts')) {
        return readFile(path, 'utf8').then(source => source.replace(
          "const matches = await cache.getByUrl('https://example.com/article/0', loader);",
          "await cache.get(loader); const matches = cache.getByUrl('https://example.com/article/0');"
        ));
      }
    },
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if (req.url?.split('?')[0] !== '/') return next();
        res.setHeader('Content-Type', 'text/html');
        res.end(`<!doctype html><script type="module" src="/tests/performance/${keyLayout ? 'key-layout' : writeLayout ? 'write-layout' : pageCache ? 'page-cache' : writes ? 'writes' : urlRead ? 'url-read' : normalize ? 'normalize' : index ? 'index' : cache ? 'cache' : searchProjection ? 'search-projection' : search ? 'search' : textMapping ? 'text-mapping' : highlightScheduling ? 'highlight-scheduling' : highlights ? 'highlights' : 'browser'}.ts"></script>`);
      });
    }
  }]
});
let chrome;
let socket;
try {
  await server.listen();
  chrome = spawn(process.env.CHROME_PATH ?? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', [
    '--headless=new', '--no-first-run', '--no-default-browser-check',
    `--user-data-dir=${profile}`, '--remote-debugging-port=0', 'about:blank'
  ], { stdio: 'ignore' });
  let launchError;
  chrome.on('error', error => { launchError = error; });
  const deadline = Date.now() + 120000;
  let port;
  while (!port) {
    if (launchError) throw launchError;
    if (Date.now() > deadline) throw new Error('Chrome startup timed out');
    try { port = (await readFile(join(profile, 'DevToolsActivePort'), 'utf8')).split('\n')[0]; }
    catch { await new Promise(resolve => setTimeout(resolve, 100)); }
  }
  const targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
  socket = new WebSocket(targets.find(target => target.type === 'page').webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.addEventListener('open', resolve, { once: true });
    socket.addEventListener('error', reject, { once: true });
  });
  let id = 0;
  const pending = new Map();
  socket.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    if (message.method === 'Runtime.exceptionThrown') console.error(JSON.stringify(message.params));
    const callback = pending.get(message.id);
    if (callback) {
      pending.delete(message.id);
      message.error ? callback.reject(new Error(JSON.stringify(message.error))) : callback.resolve(message.result);
    }
  });
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const requestId = ++id;
    const timeout = setTimeout(() => {
      pending.delete(requestId);
      reject(new Error(`${method} timed out`));
    }, 10000);
    pending.set(requestId, {
      resolve: value => { clearTimeout(timeout); resolve(value); },
      reject: error => { clearTimeout(timeout); reject(error); }
    });
    socket.send(JSON.stringify({ id: requestId, method, params }));
  });
  await send('Runtime.enable');
  if (process.env.PROFILE) {
    await send('Profiler.enable');
    await send('Profiler.start');
  }
  const query = new URLSearchParams();
  if (allocations && (highlights || search)) query.set('allocations', '1');
  if (highlightScheduling && process.argv.includes('--timer-yield')) query.set('timer-yield', '1');
  if ((urlRead || pageCache || writeLayout || keyLayout || highlights || search) && process.argv.includes('--reverse')) query.set('reverse', '1');
  if (pageCache && process.argv.includes('--legacy-v4')) query.set('legacy-v4', '1');
  await send('Page.navigate', { url: server.resolvedUrls.local[0] + (query.size ? `?${query}` : '') });
  let result;
  while (!result) {
    if (Date.now() > deadline) throw new Error('Performance run timed out');
    await new Promise(resolve => setTimeout(resolve, 100));
    const response = await send('Runtime.evaluate', { expression: 'window.__performanceResult', returnByValue: true });
    result = response.result.value;
  }
  if (result.error) throw new Error(result.error);
  if (process.env.PROFILE) {
    const { profile: cpuProfile } = await send('Profiler.stop');
    await writeFile(process.env.PROFILE, JSON.stringify(cpuProfile));
  }
  if (allocations) {
    const caseList = highlights ? '__highlightAllocationCases' : '__cacheAllocationCases';
    const describe = await send('Runtime.evaluate', {
      expression: `window.${caseList}.map(({ records, paragraphs, hiddenParagraphs, emptyContainers, name }) => ({ records, paragraphs, hiddenParagraphs, emptyContainers, name }))`, returnByValue: true
    });
    const cases = describe.result.value;
    if (!Array.isArray(cases)) throw new Error('Missing allocation cases');
    const evaluate = async expression => {
      const reply = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
      if (reply.exceptionDetails) throw new Error(JSON.stringify(reply.exceptionDetails));
    };
    const size = node => node.selfSize + node.children.reduce((sum, child) => sum + size(child), 0);
    result.allocationSamples = [];
    for (const [index, scenario] of cases.entries()) {
      const samplesBytes = [];
      const heapSamples = [];
      const allocationSites = new Map();
      for (let i = 0; i < 7; i++) {
        await evaluate(`window.${caseList}[${index}].prepare()`);
        await send('HeapProfiler.collectGarbage');
        const heapBefore = search ? await send('Runtime.getHeapUsage') : undefined;
        await send('HeapProfiler.startSampling', {
          samplingInterval: 16384, includeObjectsCollectedByMajorGC: true, includeObjectsCollectedByMinorGC: true
        });
        await evaluate(`window.${caseList}[${index}].operation()`);
        const { profile } = await send('HeapProfiler.stopSampling');
        if (search) {
          await send('HeapProfiler.collectGarbage');
          heapSamples.push({ before: heapBefore, after: await send('Runtime.getHeapUsage') });
        }
        function collectSites(node) {
          const frame = node.callFrame;
          const key = JSON.stringify([frame.functionName, frame.url, frame.lineNumber, frame.columnNumber]);
          if (node.selfSize) {
            const site = allocationSites.get(key) ?? { ...frame, samplesBytes: Array(7).fill(0) };
            site.samplesBytes[i] += node.selfSize;
            allocationSites.set(key, site);
          }
          node.children.forEach(collectSites);
        }
        collectSites(profile.head);
        await evaluate(`window.${caseList}[${index}].verify?.()`);
        samplesBytes.push(size(profile.head));
      }
      const sites = [...allocationSites.values()].map(site => ({ ...site, medianBytes: site.samplesBytes.toSorted((a, b) => a - b)[3] }))
        .sort((a, b) => b.medianBytes - a.medianBytes);
      if (samplesBytes.some((bytes, index) => sites.reduce((sum, site) => sum + site.samplesBytes[index], 0) !== bytes)) throw new Error('Allocation site totals do not match sampled bytes');
      result.allocationSamples.push({ ...scenario, medianBytes: samplesBytes.toSorted((a, b) => a - b)[3], samplesBytes, sites, ...(search ? { heapSamples } : {}) });
    }
  }
  await send('Runtime.evaluate', { expression: 'window.__performanceCleanup?.()' });
  console.log(JSON.stringify({ mode: baseline ? 'baseline' : 'working-tree', baselineRef: baseline ? baselineRef : undefined, cpuProfiled: Boolean(process.env.PROFILE), ...result }, null, 2));
} finally {
  socket?.close();
  if (chrome?.pid && chrome.exitCode === null) {
    const exited = new Promise(resolve => chrome.once('exit', resolve));
    chrome.kill();
    await exited;
  }
  await server.close();
  await rm(profile, { recursive: true, force: true });
}

scripts/search-acceptance.mjs.source:
// 临时扩展配置、合成摘录与实际管理页；不访问用户数据。
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { createServer } from 'node:net';

const firefox = process.argv.includes('--firefox');
const root = resolve(process.env.EXTENSION_PATH ?? (firefox ? '.output/firefox-mv2' : '.output/chrome-mv3'));
const profile = await mkdtemp(join(tmpdir(), 'clipsey-search-profile-'));
const artifacts = await mkdtemp(join(tmpdir(), 'clipsey-search-acceptance-'));
const passed = [], errors = [];
let context, driver, session, log = '', capabilities, evaluate, backgroundEvaluate, waitFor, reload, command;
const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
const record = name => { passed.push(name); console.log('PASS', name); };
try {
  if (firefox) {
    assert(process.env.FIREFOX_PATH && process.env.GECKODRIVER_PATH, 'Set FIREFOX_PATH and GECKODRIVER_PATH');
    assert.equal(JSON.parse(await readFile(join(root, 'manifest.json'))).manifest_version, 2);
    const socket = createServer(); await new Promise(resolve => socket.listen(0, '127.0.0.1', resolve));
    const port = socket.address().port; await new Promise(resolve => socket.close(resolve));
    driver = spawn(process.env.GECKODRIVER_PATH, ['--host', '127.0.0.1', '--port', String(port), '--profile-root', profile, '--allow-system-access'], { stdio: ['ignore', 'pipe', 'pipe'] });
    let startupError;
    driver.on('error', error => { startupError = error; });
    driver.stdout.on('data', value => { log += value; }); driver.stderr.on('data', value => { log += value; });
    const request = async (path, body, method = body === undefined ? 'GET' : 'POST') => {
      const response = await fetch(`http://127.0.0.1:${port}${path}`, { method, headers: { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(50000) });
      const reply = await response.json(); if (!response.ok || reply.value?.error) throw new Error(JSON.stringify(reply)); return reply.value;
    };
    for (let i = 0; i < 100; i++) {
      try { await request('/status'); break; } catch {
        if (startupError) throw startupError;
        if (driver.exitCode !== null || i === 99) throw new Error(log || 'Driver startup failed');
        await pause(100);
      }
    }
    const started = await request('/session', { capabilities: { alwaysMatch: { browserName: 'firefox', 'moz:firefoxOptions': { binary: process.env.FIREFOX_PATH, args: ['-headless'] } } } });
    session = started.sessionId; capabilities = started.capabilities;
    command = (path, body, method) => request(`/session/${session}${path}`, body, method);
    await command('/timeouts', { script: 40000, pageLoad: 40000, implicit: 0 });
    const addon = await command('/moz/addon/install', { path: root, temporary: true });
    await command('/moz/context', { context: 'chrome' });
    const uuid = await command('/execute/sync', { script: 'return JSON.parse(Services.prefs.getCharPref("extensions.webextensions.uuids"))[arguments[0]]', args: [addon] }); assert(uuid);
    await command('/moz/context', { context: 'content' });
    reload = () => command('/url', { url: `moz-extension://${uuid}/options.html?tab=content` });
    evaluate = async (fn, arg) => {
      const reply = await command('/execute/async', { script: `const done=arguments[1];Promise.resolve().then(()=>(${fn.toString()})(arguments[0])).then(value=>done({value}),error=>done({scriptError:String(error)+"\\n"+error.stack}));`, args: [arg ?? null] });
      if (reply.scriptError) throw new Error(reply.scriptError); return reply.value;
    };
    backgroundEvaluate = async fn => {
      const reply = await command('/execute/async', { script: `const done=arguments[0];Promise.resolve().then(()=>(${fn.toString()})(browser.extension.getBackgroundPage())).then(value=>done({value}),error=>done({scriptError:String(error)+"\\n"+error.stack}));`, args: [] });
      if (reply.scriptError) throw new Error(reply.scriptError); return reply.value;
    };
    waitFor = async (fn, arg) => {
      for (let i = 0; i < 200; i++) { if (await evaluate(fn, arg)) return; await pause(100); }
      throw new Error(`UI timeout: ${fn}`);
    };
  } else {
    assert(process.env.CHROME_PATH, 'Set CHROME_PATH to Chrome for Testing');
    const { chromium } = await import(process.env.PLAYWRIGHT_MODULE ?? 'playwright');
    context = await chromium.launchPersistentContext(profile, { executablePath: process.env.CHROME_PATH, headless: true, args: [`--disable-extensions-except=${root}`, `--load-extension=${root}`] });
    const worker = context.serviceWorkers()[0] || await context.waitForEvent('serviceworker');
    backgroundEvaluate = fn => worker.evaluate(fn);
    const page = await context.newPage(); page.on('pageerror', error => errors.push(error.message));
    const url = `chrome-extension://${new URL(worker.url()).hostname}/options.html?tab=content`;
    reload = () => page.goto(url); evaluate = (fn, arg) => page.evaluate(fn, arg);
    waitFor = (fn, arg) => page.waitForFunction(fn, arg, { timeout: 20000 });
    capabilities = { browserVersion: context.browser().version() };
  }
  await reload();
  const ready = () => !!document.querySelector('.clip-toolbar__search input');
  await waitFor(ready);
  const send = message => evaluate(message => (globalThis.browser ?? chrome).runtime.sendMessage(message), message);
  const input = query => evaluate(query => {
    const element = document.querySelector('.clip-toolbar__search input');
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(element, query);
    element.dispatchEvent(new Event('input', { bubbles: true }));
  }, query);
  const check = async (query, total, ids) => {
    await evaluate(() => { window.__searchProbe.scans = 0; window.__searchProbe.revisions = 0; });
    await input(query);
    await waitFor(({ total, ids }) => window.__searchProbe.revisions > 0 &&
      document.querySelector('.clip-toolbar__stat-value')?.textContent.trim() === String(total) &&
      !document.querySelector('.ant-spin-spinning') &&
      JSON.stringify([...document.querySelectorAll('tbody tr[data-row-key]')].map(row => row.dataset.rowKey)) === JSON.stringify(ids), { total, ids });
    return evaluate(() => window.__searchProbe);
  };
  for (const records of [100, 10000]) {
    const clips = Array.from({ length: records }, (_, i) => ({
      id: `cache-${String(i).padStart(5, '0')}`, title: i % 7 ? `Title ${i % 100}` : undefined,
      textContent: i % 2 ? `cache needle ${i}` : `other ${i}`,
      htmlContent: `<p><b>rich ${i}</b></p>`, sourceUrl: 'https://example.com/native-search',
      createdAt: new Date(1700000000000 + i * 1000).toISOString(), updatedAt: '2025-02-01T00:00:00.000Z'
    }));
    assert.equal((await send({ type: 'IMPORT_DATA', payload: { clips } })).success, true);
    await reload(); await waitFor(ready);
    await waitFor(records => document.querySelector('.clip-toolbar__stat-value')?.textContent.trim() === String(records), records);
    await evaluate(() => {
      window.__searchProbe = { scans: 0, revisions: 0 };
      const getAll = IDBObjectStore.prototype.getAll, get = IDBObjectStore.prototype.get;
      IDBObjectStore.prototype.getAll = function(...args) { if (this.name === 'clips') window.__searchProbe.scans++; return getAll.apply(this, args); };
      IDBObjectStore.prototype.get = function(key) { if (this.name === 'metadata' && key === '__clipseyClipRevision') window.__searchProbe.revisions++; return get.call(this, key); };
    });
    const matches = clips.filter(clip => clip.textContent.includes('needle'));
    const ids = matches.toReversed().slice(0, 20).map(clip => clip.id);
    assert.equal((await check('@content cache needle', matches.length, ids)).scans, Math.ceil(records / 256));
    record(`${records}: cold actual UI search returns the expected full page and total`);
    assert.equal((await check('@content CACHE NEEDLE', matches.length, ids)).scans, 0);
    record(`${records}: warm UI search checks revision and avoids repeated full-record scans`);
    await evaluate(() => document.querySelector('tbody tr[data-row-key] button').click());
    await waitFor(text => document.querySelector('.ant-modal-body b')?.textContent === text, `rich ${records - 1}`);
    await evaluate(() => document.querySelector('.ant-modal-close').click());
    record(`${records}: warm search hydrates rich content in the actual detail dialog`);
    if (records === 10000) {
      await evaluate(() => { window.__searchProbe.scans = 0; document.querySelector('thead th').click(); });
      const sorted = [...matches].sort((a, b) => (a.title ?? '').localeCompare(b.title ?? '') || a.id.localeCompare(b.id)).slice(0, 20).map(clip => clip.id);
      await waitFor(ids => JSON.stringify([...document.querySelectorAll('tbody tr[data-row-key]')].map(row => row.dataset.rowKey)) === JSON.stringify(ids), sorted);
      assert.equal((await evaluate(() => window.__searchProbe)).scans, 0);
      record('10000: title sorting reuses the snapshot, including missing titles and stable ties');
    }
    const backup = await send({ type: 'EXPORT_DATA' }); assert.equal(backup.success, true);
    assert.equal(backup.data.clips.length, records);
    const storedById = new Map(backup.data.clips.map(clip => [clip.id, clip]));
    for (const original of clips) {
      const stored = storedById.get(original.id); assert(stored);
      assert.equal(stored.htmlContent, original.htmlContent); assert(!('__clipseyUrlKey' in stored));
    }
    record(`${records}: backup preserves rich content and omits private index fields`);
  }
  const payload = { textContent: 'cache fresh', htmlContent: '<b>cache fresh</b>', sourceUrl: 'https://example.com/native-search', title: 'Saved' };
  assert.equal((await send({ type: 'SAVE_CLIP', payload })).success, true);
  const fresh = (await send({ type: 'EXPORT_DATA' })).data.clips.find(clip => clip.textContent === 'cache fresh'); assert(fresh);
  await check('@content cache fresh', 1, [fresh.id]); record('background single-record save is visible in the options search');
  assert.equal((await send({ type: 'DELETE_CLIP', payload: { id: fresh.id } })).success, true);
  await check('@content CACHE FRESH', 0, []); record('background delete invalidates the search snapshot');
  assert.equal((await send({ type: 'CLEAR_CLIPS' })).success, true);
  await check('@content needle', 0, []); record('background clear leaves no cached matches');
  const quotaClip = { id: 'quota', textContent: 'quota needle', htmlContent: '<b>Quota</b>', sourceUrl: 'https://example.com/native-search', createdAt: '2025-01-01T00:00:00.000Z' };
  assert.equal((await send({ type: 'IMPORT_DATA', payload: { clips: [quotaClip] } })).success, true);
  await check('@content quota needle', 1, ['quota']);
  assert.equal((await check('@content QUOTA NEEDLE', 1, ['quota'])).scans, 0);
  await backgroundEvaluate((scope = globalThis) => {
    const put = scope.IDBObjectStore.prototype.put, add = scope.IDBObjectStore.prototype.add;
    scope.__quotaRestore = () => { scope.IDBObjectStore.prototype.put = put; };
    scope.__quotaErrorSeen = false;
    scope.IDBObjectStore.prototype.put = function(value, key) {
      if (this.name !== 'metadata' || value.key !== '__clipseyClipRevision') return put.call(this, value, key);
      // 触发真实请求错误和默认回滚，仅替换错误身份；不填满磁盘。
      const request = add.call(this, value, key);
      Object.defineProperty(request, 'error', { get: () => new scope.DOMException('Quota full', 'QuotaExceededError') });
      request.addEventListener('error', () => { scope.__quotaErrorSeen = true; });
      return request;
    };
  });
  await evaluate(() => document.querySelector('tbody tr[data-row-key] .ant-btn-dangerous').click());
  await waitFor(() => !!document.querySelector('.ant-popover .ant-btn-primary'));
  await evaluate(() => document.querySelector('.ant-popover .ant-btn-primary').click());
  await waitFor(() => document.querySelector('.clip-toolbar__stat-value')?.textContent.trim() === '0');
  assert.equal(await backgroundEvaluate((scope = globalThis) => scope.__quotaErrorSeen), true);
  await backgroundEvaluate((scope = globalThis) => scope.__quotaRestore());
  assert((await check('@content quota needle', 0, [])).scans > 0);
  const markerMissing = await evaluate(() => new Promise((resolve, reject) => {
    const open = indexedDB.open('ClipseyDB'); open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const db = open.result, read = db.transaction('metadata').objectStore('metadata').get('__clipseyClipRevision');
      read.onerror = () => { db.close(); reject(read.error); };
      read.onsuccess = () => { db.close(); resolve(read.result === undefined); };
    };
  }));
  assert.equal(markerMissing, true);
  record('native revision request error allows actual UI deletion and markerless fresh search');
  if (firefox) {
    await command('/moz/context', { context: 'chrome' });
    const scriptErrors = await command('/execute/sync', { script: 'return Services.console.getMessageArray().filter(m=>m.sourceName?.startsWith("moz-extension://")&&!(m.flags&1)).map(m=>({message:m.errorMessage,source:m.sourceName,line:m.lineNumber}))', args: [] });
    errors.push(...scriptErrors);
  }
  assert.deepEqual(errors, []); record('no extension page script errors');
  await writeFile(join(artifacts, 'result.json'), JSON.stringify({ capabilities, root, passed, errors }, null, 2));
  console.log('ARTIFACTS', artifacts);
} finally {
  await context?.close();
  if (session) try { await command('', undefined, 'DELETE'); } catch (error) { console.error('CLEANUP', error.message); }
  driver?.kill('SIGTERM');
  if (driver) await writeFile(join(artifacts, 'geckodriver.log'), log);
  await rm(profile, { recursive: true, force: true });
}

tests/performance/search.ts.source:
import { indexedDBManager } from '../../src/background/indexeddb';
import { IndexedDBQuery } from '../../src/background/indexeddb-query';
import { searchService, type SearchQuery } from '../../src/background/services/search-service';
import type { Clip } from '../../src/types/clip';

function assert(condition: boolean, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

const getAll = IDBObjectStore.prototype.getAll;
try {
  const reverse = new URLSearchParams(location.search).has('reverse');
  let largestRead = 0;
  let reads = 0;
  IDBObjectStore.prototype.getAll = function(...args) {
    const request = getAll.apply(this, args);
    if (this.name === 'clips') reads += 1;
    request.addEventListener('success', () => { largestRead = Math.max(largestRead, request.result.length); });
    return request;
  };
  const results = [];
  let allocationRecords = 0;
  (window as any).__cacheAllocationCases = [];
  for (const records of reverse ? [10000, 100] : [100, 10000]) {
    await indexedDBManager.clear('clips');
    const clips: Clip[] = Array.from({ length: records }, (_, i) => ({
      id: String(i).padStart(5, '0'),
      title: i % 7 ? `Title ${i % 100}` : undefined,
      textContent: `${i % 2 ? '测试 Needle' : 'plain'} ${'Performance fixture '.repeat(32)}`,
      htmlContent: `<p>${'Rich content '.repeat(64)}</p>`,
      sourceUrl: `https://example.com/article/${i % 100}`,
      createdAt: new Date(Date.UTC(2025, 0, 1) + Math.floor(i / 5) * 1000).toISOString()
    }));
    await IndexedDBQuery.bulkPut('clips', clips, { batchSize: 1000 });
    const queries: SearchQuery[] = [
      { type: 'content', keyword: 'NEEDLE', sortBy: 'createdAt', sortOrder: 'desc', page: Math.max(1, records / 100) },
      { type: 'website', keyword: '/article/1', sortBy: 'sourceUrl', sortOrder: 'asc', page: 1 },
      { type: 'all', keyword: '测试', sortBy: 'textContent', sortOrder: 'asc', page: 2 },
      { type: 'content', keyword: 'absent', sortBy: 'createdAt', sortOrder: 'asc', page: 1 },
      { type: 'all', keyword: 'needle', sortBy: 'title', sortOrder: 'asc', page: 2 },
      { type: 'all', keyword: '', sortBy: 'title', sortOrder: 'desc', page: Math.max(1, records / 100) }
    ];
    const scenarios = [];
    for (const query of reverse ? queries.toReversed() : queries) {
      const fields = query.type === 'content' ? ['textContent'] : query.type === 'website' ? ['sourceUrl'] : ['title', 'sourceUrl', 'textContent'];
      const expected = clips.filter(clip => fields.some(field => String(clip[field as keyof Clip] ?? '').toLowerCase().includes(query.keyword!.toLowerCase())));
      const direction = query.sortOrder === 'asc' ? 1 : -1;
      const sortBy = query.sortBy!;
      expected.sort((a, b) => direction * (sortBy === 'title'
        ? (a.title ?? '').localeCompare(b.title ?? '') || a.id.localeCompare(b.id)
        : indexedDB.cmp(a[sortBy]!, b[sortBy]!) || indexedDB.cmp(a.id, b.id)));
      const page = query.page!;
      const expectedPage = expected.slice((page - 1) * 20, page * 20);
      largestRead = 0;
      async function run() {
        const result = await searchService.search(query);
        assert(result.total === expected.length, 'Wrong exact count');
        assert(JSON.stringify(result.items) === JSON.stringify(expectedPage), 'Wrong search page/order/full fields');
      }
      // 实际写入使候选缓存失效；准备不计时，冷指应用快照而非磁盘或后台启动。
      const coldSamplesMs = [];
      for (let i = -1; i < 7; i++) {
        await indexedDBManager.put('clips', clips[0]!);
        const start = performance.now(); await run();
        if (i >= 0) coldSamplesMs.push(performance.now() - start);
      }
      const coldReads = reads; reads = 0;
      await run();
      const samplesMs = [];
      for (let i = 0; i < 7; i++) {
        const start = performance.now();
        await run();
        samplesMs.push(performance.now() - start);
      }
      assert(largestRead <= 256, 'Unbounded scan');
      scenarios.push({ query, total: expected.length, largestRead, coldReads, warmReads: reads, coldMedianMs: coldSamplesMs.toSorted((a, b) => a - b)[3], coldSamplesMs, medianMs: samplesMs.toSorted((a, b) => a - b)[3], samplesMs });
      reads = 0;
      if (new URLSearchParams(location.search).has('allocations') && (query === queries[0] || query === queries[1])) {
        for (const mode of ['cold', 'warm']) (window as any).__cacheAllocationCases.push({
          records, name: `${query.type}-${mode}`,
          prepare: async () => {
            if (allocationRecords !== records) {
              await indexedDBManager.clear('clips');
              await IndexedDBQuery.bulkPut('clips', clips, { batchSize: 1000 });
              allocationRecords = records;
            }
            await indexedDBManager.put('clips', clips[0]!);
            if (mode === 'warm') await run();
          }, operation: run
        });
      }
    }
    results.push({ records, scenarios });
  }
  (window as any).__performanceResult = { userAgent: navigator.userAgent, scenario: 'search', reverse, results };
  (window as any).__performanceCleanup = () => indexedDBManager.close();
} catch (error) {
  (window as any).__performanceResult = { error: String(error) };
} finally {
  indexedDBManager.close();
  IDBObjectStore.prototype.getAll = getAll;
}

